"""A tiny spreadsheet formula engine (see README.md for the semantics).

A cell value is either a bare number (``"2"``) or a formula (``"=A+3"``).
``evaluate`` parses every cell once, then resolves cells lazily in dependency
order, raising :class:`CycleError` if a cell reaches itself.
"""

import re


class CycleError(Exception):
    """Raised when cell references form a dependency cycle."""


# --- tokenizer ---------------------------------------------------------------

_TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<number>\d+\.\d*|\.\d+|\d+)
      | (?P<name>[A-Za-z]+\d*)
      | (?P<op>[-+*/^()])
    )
    """,
    re.VERBOSE,
)

NUMBER, NAME, OP, END = "number", "name", "op", "end"


def _tokenize(text):
    """Return a list of ``(kind, value)`` tokens, terminated by ``(END, None)``."""
    tokens = []
    pos = 0
    while pos < len(text):
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            if text[pos:].strip() == "":
                break
            raise ValueError("unexpected character %r at %d" % (text[pos], pos))
        pos = match.end()
        kind = match.lastgroup
        tokens.append((kind, match.group(kind)))
    tokens.append((END, None))
    return tokens


# --- parser ------------------------------------------------------------------
#
# expr   := term (('+' | '-') term)*
# term   := unary (('*' | '/') unary)*
# unary  := '-' unary | '+' unary | power        # looser than '^': -2^2 == -(2^2)
# power  := atom ('^' unary)?                    # right-associative
# atom   := number | name | '(' expr ')'
#
# An AST node is a tuple: ('num', v) | ('ref', name) | ('neg', x) | (op, l, r).


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        return self._tokens[self._pos]

    def _next(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _accept(self, value):
        kind, text = self._peek()
        if kind == OP and text == value:
            self._pos += 1
            return True
        return False

    def parse(self):
        node = self.expr()
        kind, text = self._peek()
        if kind != END:
            raise ValueError("unexpected token %r" % (text,))
        return node

    def expr(self):
        node = self.term()
        while True:
            if self._accept("+"):
                node = ("+", node, self.term())
            elif self._accept("-"):
                node = ("-", node, self.term())
            else:
                return node

    def term(self):
        node = self.unary()
        while True:
            if self._accept("*"):
                node = ("*", node, self.unary())
            elif self._accept("/"):
                node = ("/", node, self.unary())
            else:
                return node

    def unary(self):
        if self._accept("-"):
            return ("neg", self.unary())
        if self._accept("+"):
            return self.unary()
        return self.power()

    def power(self):
        base = self.atom()
        if self._accept("^"):
            # right-associative, and the exponent may itself be negated (2^-3)
            return ("^", base, self.unary())
        return base

    def atom(self):
        kind, text = self._next()
        if kind == NUMBER:
            return ("num", float(text))
        if kind == NAME:
            return ("ref", text)
        if kind == OP and text == "(":
            node = self.expr()
            if not self._accept(")"):
                raise ValueError("expected ')'")
            return node
        raise ValueError("unexpected token %r" % ("end of input" if text is None else text,))


def _parse_cell(name, text):
    """Parse one cell's source into an AST."""
    if not isinstance(text, str):
        raise ValueError("cell %s: expected a string, got %r" % (name, type(text).__name__))
    source = text.strip()
    if source.startswith("="):
        try:
            return _Parser(_tokenize(source[1:])).parse()
        except ValueError as exc:
            raise ValueError("cell %s: %s" % (name, exc))
    try:
        return ("num", float(source))
    except ValueError:
        raise ValueError("cell %s: %r is neither a number nor a formula" % (name, text))


# --- evaluation --------------------------------------------------------------


def _refs(node, out):
    """Collect the cell names referenced by ``node`` into ``out`` (in order)."""
    tag = node[0]
    if tag == "ref":
        out.append(node[1])
    elif tag == "num":
        pass
    elif tag == "neg":
        _refs(node[1], out)
    else:
        _refs(node[1], out)
        _refs(node[2], out)
    return out


def _eval(node, values):
    """Evaluate an AST; every referenced cell must already be in ``values``."""
    tag = node[0]
    if tag == "num":
        return node[1]
    if tag == "ref":
        return values[node[1]]
    if tag == "neg":
        return -_eval(node[1], values)
    left = _eval(node[1], values)
    right = _eval(node[2], values)
    if tag == "+":
        return left + right
    if tag == "-":
        return left - right
    if tag == "*":
        return left * right
    if tag == "/":
        return left / right
    return left ** right


_VISITING, _DONE = 1, 2


def evaluate(cells):
    """Compute every cell in ``cells``, returning ``{name: float}``.

    Raises :class:`CycleError` on any dependency cycle, ``KeyError`` for a
    reference to an unknown cell, and ``ZeroDivisionError`` for division by zero.
    """
    asts = {}
    deps = {}
    for name, text in cells.items():
        node = _parse_cell(name, text)
        asts[name] = node
        deps[name] = _refs(node, [])

    values = {}
    state = {}
    # Iterative depth-first resolution, so that long reference chains do not
    # exhaust the interpreter's recursion limit.
    for root in asts:
        if state.get(root) == _DONE:
            continue
        stack = [root]
        while stack:
            name = stack[-1]
            status = state.get(name)
            if status == _DONE:
                stack.pop()
                continue
            if status == _VISITING:
                # every dependency has been resolved by now
                stack.pop()
                values[name] = _eval(asts[name], values)
                state[name] = _DONE
                continue
            state[name] = _VISITING
            for dep in deps[name]:
                dep_status = state.get(dep)
                if dep_status == _DONE:
                    continue
                if dep_status == _VISITING:
                    raise CycleError(_cycle_message(stack, state, dep))
                if dep not in asts:
                    raise KeyError(dep)
                stack.append(dep)
    return values


def _cycle_message(stack, state, dep):
    chain = [name for name in stack if state.get(name) == _VISITING]
    chain = chain[chain.index(dep):] + [dep]
    return "cycle: " + " -> ".join(chain)

